// Groebner basis benchmarks (sagebrush articles/groebner), part 2; generated by
// bench/groebner/make_magma_online.py.  Each line: name, #basis, CPU and wall seconds.
a, b, c := GetVersion(); printf "Magma %o.%o-%o\n", a, b, c;
// calibration: big-integer arithmetic (GMP) and the interpreter, to compare machines
t := Cputime(); x := 3^5000000; for k in [1..4] do y := x*x; z := y div (x + 1); end for; printf "calibration GMP: %o s\n", Cputime(t);
t := Cputime(); s := 0; for i in [1..2000000] do s +:= (i*i) mod 7; end for; printf "calibration loop: %o s\n", Cputime(t);
procedure bench(name, I)
  t := Cputime(); w := Realtime();
  G := GroebnerBasis(I);
  printf "%o: %o elements, cpu %o s, wall %o s\n", name, #G, Cputime(t), Realtime(w);
end procedure;
P<x0,x1,x2,x3,x4,x5,x6,x7> := PolynomialRing(Rationals(), 8, "lex");
bench("katsura-7 QQ lex", ideal<P | x0+2*x1+2*x2+2*x3+2*x4+2*x5+2*x6+2*x7-1, x0^2+2*x1^2+2*x2^2+2*x3^2+2*x4^2+2*x5^2+2*x6^2+2*x7^2-x0, 2*x0*x1+2*x1*x2+2*x2*x3+2*x3*x4+2*x4*x5+2*x5*x6+2*x6*x7-x1, x1^2+2*x0*x2+2*x1*x3+2*x2*x4+2*x3*x5+2*x4*x6+2*x5*x7-x2, 2*x1*x2+2*x0*x3+2*x1*x4+2*x2*x5+2*x3*x6+2*x4*x7-x3, x2^2+2*x1*x3+2*x0*x4+2*x1*x5+2*x2*x6+2*x3*x7-x4, 2*x2*x3+2*x1*x4+2*x0*x5+2*x1*x6+2*x2*x7-x5, x3^2+2*x2*x4+2*x1*x5+2*x0*x6+2*x1*x7-x6>);
